mapper.select:
SELECT 
FROM post_comment c

WHERE c.post_id = #{postId}
  AND c.root_id = '0'
  AND (c.state = 'NORMAL'

          OR (c.state = 'PENDING_REVIEW' AND c.user_id = #{viewerId})
          OR (c.state = 'REJECTED' AND c.user_id = #{viewerId})

  )
ORDER BY c.create_time, c.comment_id
LIMIT #{offset}, #{limit}

SELECT comment_id
FROM post_comment_feed_index
WHERE post_id = #{postId}
ORDER BY like_count DESC, create_time, comment_id
LIMIT #{offset}, #{limit}

SELECT c.id, c.comment_id, c.post_id, c.user_id, c.content, c.state, c.root_id, c.parent_id, c.create_time, c.update_time, u.nickname AS author_nickname, p.user_id AS reply_to_user_id, pu.nickname AS reply_to_nickname, cr.reason AS reject_reason FROM post_comment c LEFT JOIN bs_user u ON c.user_id = u.user_id LEFT JOIN post_comment p ON c.parent_id = p.comment_id LEFT JOIN bs_user pu ON p.user_id = pu.user_id LEFT JOIN content_review cr ON cr.target_type = 'COMMENT' AND cr.target_id = c.comment_id AND cr.action = 'REJECT' WHERE c.root_id = #{rootId} AND (c.state = 'NORMAL'
OR (c.state IN ('PENDING_REVIEW', 'REJECTED') AND c.user_id = #{viewerId})
) ORDER BY c.create_time, c.comment_id LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM post_comment
WHERE root_id = #{rootId}
  AND (state = 'NORMAL'

          OR (state IN ('PENDING_REVIEW', 'REJECTED') AND user_id = #{viewerId})

  )

SELECT user_id
FROM post_comment_like
WHERE comment_id = #{commentId}
  AND user_id IN
#{userId}

